\begin{aligned}
\operatorname{MonoDef}_{R}(f):=\exists X:\mathsf O\exists Y:\mathsf O(&Arr(f,X,Y)\wedge
\forall Z:\mathsf O\forall g:\mathsf A\forall h:\mathsf A\\
&((Arr(g,Z,X)\wedge Arr(h,Z,X)\wedge f\circ g\doteq_{\mathsf A}f\circ h)
\to g\doteq_{\mathsf A}h)),
\end{aligned}

\begin{aligned}
\operatorname{EpiDef}_{R}(f):=\exists X:\mathsf O\exists Y:\mathsf O(&Arr(f,X,Y)\wedge
\forall Z:\mathsf O\forall g:\mathsf A\forall h:\mathsf A\\
&((Arr(g,Y,Z)\wedge Arr(h,Y,Z)\wedge g\circ f\doteq_{\mathsf A}h\circ f)
\to g\doteq_{\mathsf A}h)),
\end{aligned}

\begin{aligned}
\operatorname{RelSpan}_{R}(R,X,Y,p,q):={}&Proj_0(R,p)\wedge Proj_1(R,q)
\wedge Arr(p,R,X)\wedge Arr(q,R,Y)\\
&\wedge\forall p':\mathsf A(Proj_0(R,p')\to p'\doteq_{\mathsf A}p)
\wedge\forall q':\mathsf A(Proj_1(R,q')\to q'\doteq_{\mathsf A}q).
\end{aligned}
